    const period = periodOf(periods, c.date);
    const person = byId.get(c.person);
    if (period === undefined || person === undefined || !countedOn(c, person, period.to)) continue;'''
assert old in s
s=s.replace(old,new)
s=s.replace('''/** Each period's live due-total (in hundredths, by name): the due of the counted (OPEN and SETTLED, but not an unbound
 *  OPEN one within its person's hold) claims whose date falls in it (a claim with no rate adds nothing). */''','''/** Each period's live due-total (in hundredths, by name): the due now of the claims whose date falls in it that counted
 *  at the end of its last day (see {@link countedOn}: OPEN, PENDING or SETTLED then by their status log, but not a
 *  deferred one, nor an unbound open one within its person's hold); a claim with no rate adds nothing. */''')
open(p,'w').write(s)
